def reachable_cycle_regions(request):
    """Return {'regions': [...], 'reachable': {station: [indices]}}.

    regions: strongly connected vertex groups containing at least one directed
    cycle. Each group is {'stations': [...], 'transitions': [...]} where
    transitions are the original edges internal to the group (parallel rows
    preserved). reachable maps every station ID to the indices of the listed
    groups it can reach.
    """
    stations = request["stations"]
    transitions = request["transitions"]

    # Adjacency for reachability (ignore gains).
    adj = {s: [] for s in stations}
    for t in transitions:
        adj[t["from"]].append(t["to"])

    # Tarjan strongly connected components.
    index = {}
    low = {}
    on_stack = set()
    stack = []
    counter = [0]
    comps = []

    def strongconnect(v):
        index[v] = low[v] = counter[0]
        counter[0] += 1
        stack.append(v)
        on_stack.add(v)
        for w in adj[v]:
            if w not in index:
                strongconnect(w)
                low[v] = min(low[v], low[w])
            elif w in on_stack:
                low[v] = min(low[v], index[w])
        if low[v] == index[v]:
            comp = []
            while True:
                w = stack.pop()
                on_stack.discard(w)
                comp.append(w)
                if w == v:
                    break
            comps.append(comp)

    for s in stations:
        if s not in index:
            strongconnect(s)

    # A component contains a cycle iff it has an internal edge (self-loop or
    # edge between two members). For a single-vertex component that means a
    # self-loop.
    regions = []
    for comp in comps:
        members = set(comp)
        internal = [t for t in transitions
                    if t["from"] in members and t["to"] in members]
        if internal:
            regions.append({
                "stations": sorted(comp),
                "transitions": internal,
            })

    # Map station -> region index (region containing that station).
    station_region = {}
    for i, region in enumerate(regions):
        for s in region["stations"]:
            station_region[s] = i

    # Reachability over the condensation graph (regions as nodes).
    n = len(regions)
    region_adj = [set() for _ in range(n)]
    for t in transitions:
        f = station_region.get(t["from"])
        g = station_region.get(t["to"])
        if f is not None and g is not None and f != g:
            region_adj[f].add(g)

    # For each region, the set of regions reachable from it (including itself).
    reach_from = []
    for i in range(n):
        seen = {i}
        stack = [i]
        while stack:
            cur = stack.pop()
            for nxt in region_adj[cur]:
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        reach_from.append(seen)

    reachable = {}
    for s in stations:
        r = station_region.get(s)
        if r is None:
            reachable[s] = []
        else:
            reachable[s] = sorted(reach_from[r])

    return {"regions": regions, "reachable": reachable}

from fractions import Fraction


def maximum_cycle_mean(region):
    """Return [numerator, denominator] of the greatest mean gain over any
    nonempty directed cycle in a cycle-containing strongly connected region.

    Uses Karp's minimum cycle mean algorithm on negated gains to find the
    maximum mean gain exactly. Parallel edges and self-loops are preserved.
    """
    stations = region["stations"]
    transitions = region["transitions"]

    n = len(stations)
    idx = {s: i for i, s in enumerate(stations)}

    # Negate gains so maximum mean gain becomes minimum mean gain.
    edges = [(idx[t["from"]], idx[t["to"]], -t["gain"]) for t in transitions]

    INF = float("inf")
    # dp[k][v] = min weight of a walk of exactly k edges ending at v.
    dp = [[INF] * n for _ in range(n + 1)]
    dp[0][0] = 0

    for k in range(1, n + 1):
        for u, v, w in edges:
            if dp[k - 1][u] != INF:
                cand = dp[k - 1][u] + w
                if cand < dp[k][v]:
                    dp[k][v] = cand

    best = None  # minimum mean (of negated gains)
    for v in range(n):
        if dp[n][v] == INF:
            continue
        max_over_k = None
        for k in range(n):
            if dp[k][v] == INF:
                continue
            val = Fraction(dp[n][v] - dp[k][v], n - k)
            if max_over_k is None or val > max_over_k:
                max_over_k = val
        if max_over_k is not None:
            if best is None or max_over_k < best:
                best = max_over_k

    # best is the minimum mean of negated gains == negative of maximum mean.
    result = -best
    return [result.numerator, result.denominator]

