                on_stack.discard(w)
                comp.append(w)
                if w == v:
                    break
            comps.append(comp)

    for s in stations:
        if s not in index:
            strongconnect(s)

    # A component contains a cycle iff it has an internal edge (self-loop or
    # edge between two members). For a single-vertex component that means a
    # self-loop.
    regions = []
    for comp in comps:
        members = set(comp)
        internal = [t for t in transitions
                    if t["from"] in members and t["to"] in members]
        if internal:
            regions.append({
                "stations": sorted(comp),
                "transitions": internal,
            })

    # Map station -> region index (region containing that station).
    station_region = {}
    for i, region in enumerate(regions):
        for s in region["stations"]:
            station_region[s] = i

    # Reachability over the condensation graph (regions as nodes).
    n = len(regions)
    region_adj = [set() for _ in range(n)]
    for t in transitions:
        f = station_region.get(t["from"])
        g = station_region.get(t["to"])
        if f is not None and g is not None and f != g:
