            cur = stack.pop()
            for nxt in adj[cur]:
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        idxs = set()
        for i, region in enumerate(regions):
            if any(m in seen for m in region["stations"]):
                idxs.add(i)
        reachable[s] = sorted(idxs)

    return {"regions": regions, "reachable": reachable}

