class SustainableYieldTests(unittest.TestCase):
    def test_public_fixture(self):
        # Independent re-derivation of the public example.
        request = {
            "stations": ["A", "B", "C", "D", "E", "X"],
            "transitions": [
                {"from": "A", "to": "B", "gain": 100},
                {"from": "B", "to": "C", "gain": 0},
                {"from": "C", "to": "B", "gain": 10},
                {"from": "A", "to": "D", "gain": 0},
                {"from": "D", "to": "E", "gain": 0},
                {"from": "E", "to": "X", "gain": 0},
                {"from": "X", "to": "D", "gain": 12},
            ],
        }
        payload = {"request": request}
        contract = {"task": "F20"}
        result = call_candidate("packages/analysis/engine.py", "transform",
                                args=[payload, contract])
        self.assertIn("sustainable", result)
        sus = result["sustainable"]
        self.assertEqual(set(sus), set(request["stations"]))
        # B<->C cycle: (0+10)/2 = 5
        self.assertEqual(Fraction(*sus["B"]), Fraction(5, 1))
        self.assertEqual(Fraction(*sus["C"]), Fraction(5, 1))
        # D->E->X->D cycle: (0+0+12)/3 = 4
        self.assertEqual(Fraction(*sus["D"]), Fraction(4, 1))
        self.assertEqual(Fraction(*sus["E"]), Fraction(4, 1))
        self.assertEqual(Fraction(*sus["X"]), Fraction(4, 1))
        # A reaches B via A->B, so it can sustain the B<->C cycle mean 5.
        self.assertEqual(Fraction(*sus["A"]), Fraction(5, 1))

    def test_approach_route_reaches_cycle(self):
        # A finite approach route affects reachability but not the mean.
        request = {
            "stations": ["S", "A", "B"],
            "transitions": [
                {"from": "S", "to": "A", "gain": 999},
                {"from": "A", "to": "B", "gain": 2},
                {"from": "B", "to": "A", "gain": 4},
            ],
        }
        payload = {"request": request}
        contract = {"task": "F20"}
        result = call_candidate("packages/analysis/engine.py", "transform",
                                args=[payload, contract])
        sus = result["sustainable"]
        # A<->B cycle mean = (2+4)/2 = 3
        self.assertEqual(Fraction(*sus["A"]), Fraction(3, 1))
        self.assertEqual(Fraction(*sus["B"]), Fraction(3, 1))
        # S reaches the cycle through A, so it also sustains 3.
        self.assertEqual(Fraction(*sus["S"]), Fraction(3, 1))

    def test_no_cycle_is_null(self):
        # A station with no reachable cycle yields null.
        request = {
            "stations": ["A", "B"],
            "transitions": [
                {"from": "A", "to": "B", "gain": 5},
            ],
        }
        payload = {"request": request}
        contract = {"task": "F20"}
        result = call_candidate("packages/analysis/engine.py", "transform",
                                args=[payload, contract])
        sus = result["sustainable"]
        self.assertIsNone(sus["A"])
        self.assertIsNone(sus["B"])

    def test_self_loop_negative_mean(self):
        # A single self-loop is a cycle; negative means are preserved.
        request = {
            "stations": ["A"],
            "transitions": [
                {"from": "A", "to": "A", "gain": -7},
            ],
        }
        payload = {"request": request}
        contract = {"task": "F20"}
        result = call_candidate("packages/analysis/engine.py", "transform",
                                args=[payload, contract])
        sus = result["sustainable"]
        self.assertEqual(Fraction(*sus["A"]), Fraction(-7, 1))

    def test_parallel_edges_and_fraction(self):
        # Parallel edges are independent; greatest mean may be a fraction.
        request = {
            "stations": ["A", "B"],
            "transitions": [
                {"from": "A", "to": "B", "gain": -5},
                {"from": "A", "to": "B", "gain": -2},
                {"from": "B", "to": "A", "gain": -3},
                {"from": "A", "to": "A", "gain": -6},
            ],
        }
        payload = {"request": request}
        contract = {"task": "F20"}
        result = call_candidate("packages/analysis/engine.py", "transform",
                                args=[payload, contract])
        sus = result["sustainable"]
        # Best cycle: A->B(-5) + B->A(-3) = -8 over 2 edges = -4.
        # A->B(-2)+B->A(-3) = -5/2 = -2.5 (better). Self-loop -6.
        # Greatest mean = -5/2.
        self.assertEqual(Fraction(*sus["A"]), Fraction(-5, 2))
        self.assertEqual(Fraction(*sus["B"]), Fraction(-5, 2))

    def test_isolated_station_null(self):
        # An isolated station reaches no cycle.
        request = {
            "stations": ["A", "B", "C"],
            "transitions": [
                {"from": "A", "to": "B", "gain": 1},
                {"from": "B", "to": "A", "gain": 1},
            ],
        }
        payload = {"request": request}
        contract = {"task": "F20"}
        result = call_candidate("packages/analysis/engine.py", "transform",
                                args=[payload, contract])
        sus = result["sustainable"]
        self.assertEqual(Fraction(*sus["A"]), Fraction(1, 1))
        self.assertEqual(Fraction(*sus["B"]), Fraction(1, 1))
        self.assertIsNone(sus["C"])

    def test_caller_inputs_unchanged(self):
        # transform must leave caller inputs intact.
        request = {
            "stations": ["A", "B"],
            "transitions": [
                {"from": "A", "to": "B", "gain": 1},
                {"from": "B", "to": "A", "gain": 1},
            ],
        }
        payload = {"request": request}
        contract = {"task": "F20"}
        snapshot = {"stations": list(request["stations"]),
                    "transitions": [dict(t) for t in request["transitions"]]}
        call_candidate("packages/analysis/engine.py", "transform",
                       args=[payload, contract])
        self.assertEqual(request["stations"], snapshot["stations"])
        self.assertEqual(request["transitions"], snapshot["transitions"])


